def migrar_contratos_existentes(apps, schema_editor):
    """
    Pasa a cada vestido el tipo, la ruta y el precio que antes se
    tomaban de la simulación (o del propio contrato), y completa la
    clienta del contrato.
    """
    Contrato = apps.get_model("core", "Contrato")

    for contrato in Contrato.objects.all():
        simulacion = contrato.simulacion
        tipo_vestido_id = contrato.tipo_vestido_id or (
            simulacion.tipo_vestido_id if simulacion else None
        )
        ruta_id = contrato.ruta_id or (
            simulacion.ruta_id if simulacion else None
        )

        campos = []
        if contrato.cliente_id is None and simulacion is not None:
            contrato.cliente_id = simulacion.cliente_id
            campos.append("cliente")

        if simulacion is not None:
            contrato.servicio_venta = True
            contrato.servicio_confeccion = True
            campos += ["servicio_venta", "servicio_confeccion"]

        if campos:
            contrato.save(update_fields=campos)

        precio = simulacion.precio_unitario if simulacion else Decimal("0")

        for vestido in contrato.vestidos.all():
            vestido.tipo_vestido_id = tipo_vestido_id
            vestido.ruta_id = ruta_id
            vestido.precio = precio
            vestido.modalidad = "VENTA"
            vestido.save(update_fields=[
                "tipo_vestido", "ruta", "precio", "modalidad",
            ])


